insert into news (date, title_ku, title_tr, title_en, body_ku, body_tr, body_en) values ('2026-10-08', 'Single ya nû: “Ez Dînim”', 'Yeni single: “Ez Dînim”', 'New single: “Ez Dînim”', 'Strana nû ya Azad Bedran “Ez Dînim” ji 8ê Kewçêrê ve li ser hemû platformên muzîkê ye.', 'Azad Bedran’ın yeni şarkısı “Ez Dînim” 8 Ekim’den beri tüm dijital platformlarda.', 'Azad Bedran’s new single “Ez Dînim” has been out on all streaming platforms since October 8.');
insert into news (date, title_ku, title_tr, title_en, body_ku, body_tr, body_en) values ('2026-09-24', 'Bi Suleyman re: “Tu Çîrokek Bê Hempa”', 'Suleyman ile: “Tu Çîrokek Bê Hempa”', 'With Suleyman: “Tu Çîrokek Bê Hempa”', 'Azad Bedran û Suleyman bi hev re strana “Tu Çîrokek Bê Hempa” weşandin.', 'Azad Bedran ve Suleyman’ın birlikte seslendirdiği “Tu Çîrokek Bê Hempa” yayında.', 'Azad Bedran and Suleyman have released their joint single “Tu Çîrokek Bê Hempa”.');
insert into news (date, title_ku, title_tr, title_en, body_ku, body_tr, body_en) values ('2026-07-31', 'Albûma zindî: “Evîna Azad (Live)”', 'Canlı albüm: “Evîna Azad (Live)”', 'Live album: “Evîna Azad (Live)”', '13 stran bi enerjiya sahneyê: albûma zindî ya Azad Bedran niha li ser hemû platforman e.', 'Sahnenin enerjisiyle 13 şarkı: Azad Bedran’ın canlı albümü tüm platformlarda.', '13 songs with all the energy of the stage: Azad Bedran’s live album is out now.');
insert into news (date, title_ku, title_tr, title_en, body_ku, body_tr, body_en) values ('2026-03-26', '“Amedspor Geliyor”', '“Amedspor Geliyor”', '“Amedspor Geliyor”', 'Strana nû ji bo Amedsporê: “Amedspor Geliyor” niha derket.', 'Amedspor için yeni şarkı: “Amedspor Geliyor” yayında.', 'A new song for Amedspor: “Amedspor Geliyor” is out now.');
